const defaultData = {
  onboard: 0, screen: 'onboarding', tab: 'home', name: 'Alex', goal: 'Allenarmi 3 volte a settimana',
  level: 7, xp: 740, workouts: 24, streak: 5, minutes: 1380, period: 'week',
  selectedRoutine: 0, activeRoutine: null, startedAt: null, completed: {},
  routines: [
    { name: 'Upper Body Power', focus: 'Petto · Spalle · Tricipiti', duration: 55, color: '💪', exercises: [
      { name: 'Panca piana', detail: '4 serie · 8 ripetizioni', sets: 4, reps: 8, weight: 60 },
      { name: 'Shoulder press', detail: '3 serie · 10 ripetizioni', sets: 3, reps: 10, weight: 20 },
      { name: 'Alzate laterali', detail: '3 serie · 12 ripetizioni', sets: 3, reps: 12, weight: 8 },
      { name: 'Pushdown tricipiti', detail: '3 serie · 12 ripetizioni', sets: 3, reps: 12, weight: 25 }
    ]},
    { name: 'Leg Day', focus: 'Gambe · Glutei · Core', duration: 60, color: '⚡', exercises: [
      { name: 'Squat', detail: '4 serie · 8 ripetizioni', sets: 4, reps: 8, weight: 70 },
      { name: 'Affondi', detail: '3 serie · 10 ripetizioni', sets: 3, reps: 10, weight: 16 },
      { name: 'Leg curl', detail: '3 serie · 12 ripetizioni', sets: 3, reps: 12, weight: 35 },
      { name: 'Plank', detail: '3 serie · 45 secondi', sets: 3, reps: 45, weight: 0 }
    ]},
    { name: 'Pull & Back', focus: 'Schiena · Bicipiti', duration: 50, color: '↗', exercises: [
      { name: 'Lat machine', detail: '4 serie · 10 ripetizioni', sets: 4, reps: 10, weight: 45 },
      { name: 'Rematore', detail: '3 serie · 10 ripetizioni', sets: 3, reps: 10, weight: 35 },
      { name: 'Curl manubri', detail: '3 serie · 12 ripetizioni', sets: 3, reps: 12, weight: 12 }
    ]}
  ]
};
const saved = JSON.parse(localStorage.getItem('corefit-demo') || 'null');
let state = saved ? { ...defaultData, ...saved, routines: defaultData.routines } : structuredClone(defaultData);
const app = document.getElementById('app');
const e = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save = () => localStorage.setItem('corefit-demo', JSON.stringify(state));
const go = screen => { state.screen = screen; save(); render(); };
const nav = () => `<nav class="bottom-nav" aria-label="Navigazione principale">${[['home','⌂','Home'],['routines','▦','Routine'],['stats','▥','Statistiche'],['profile','◉','Profilo']].map(([id,icon,label])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}" aria-label="${label}" aria-current="${state.tab===id?'page':'false'}"><span class="nav-symbol">${icon}</span>${label}</button>`).join('')}</nav>`;
const shell = (content, showNav=true) => `<section class="screen">${content}</section>${showNav?nav():''}`;
const brand = `<div class="brand">CORE<span>FIT</span></div>`;
const top = (right='') => `<div class="topline">${brand}${right}</div>`;
function onboarding(){
  const slides = [
    ['Ogni allenamento è un passo avanti.','Tieni traccia delle tue sessioni e rendi visibili i tuoi progressi.'],
    ['Le tue routine, a modo tuo.','Organizza gli esercizi e concentrati su quello che conta.'],
    ['Allenati. Guadagna XP. Evolvi.','Trasforma la costanza in livelli, traguardi e motivazione.']
  ];
  const [title, desc] = slides[state.onboard];
  return shell(`<div class="onboard-screen" style="min-height:100%">${brand}<div class="onboard-art art-${state.onboard}" aria-hidden="true"></div><div class="eyebrow">Benvenuto in CoreFit</div><h1 class="title" style="font-size:34px">${title}</h1><p class="sub">${desc}</p><div class="dots">${slides.map((_,i)=>`<span class="${i===state.onboard?'active':''}"></span>`).join('')}</div><div class="spacer"></div><button class="primary" data-action="next-onboard">${state.onboard===2?'Inizia ora':'Continua'}</button><button class="small-btn" data-action="skip-onboard" style="align-self:center;margin-top:12px">Salta introduzione</button></div>`,false);
}
function login(){return shell(`<div class="auth-screen" style="min-height:100%">${brand}<div class="eyebrow" style="margin-top:65px">Benvenuto</div><h1 class="title">Il tuo percorso<br>inizia qui.</h1><p class="sub">Accedi per continuare il tuo allenamento.</p><form id="login-form"><label class="field"><span>Email</span><input name="email" type="email" placeholder="nome@email.com" autocomplete="email" required></label><label class="field"><span>Password</span><input name="password" type="password" placeholder="••••••••" autocomplete="current-password" required minlength="4"></label><button class="primary" type="submit" style="margin-top:10px">Accedi</button></form><div class="spacer"></div><button class="secondary" data-action="demo-login">Esplora la demo</button><p class="demo-note">Prototipo: l’accesso è simulato. Nessun dato viene inviato a un server.</p></div>`,false)}
function home(){const first=state.routines[0];return shell(`${top(`<button class="avatar" data-action="profile" aria-label="Apri profilo">${e(state.name[0]||'A')}</button>`)}<div class="eyebrow">Giovedì · il tuo percorso</div><h1 class="title">Ciao, ${e(state.name)} <span style="color:#c9fa64">✳</span></h1><p class="sub">Continua così: ogni sessione conta.</p><div class="section-heading"><h2>Il prossimo passo</h2><span class="pill">✦ ${state.streak} giorni di fila</span></div><div class="hero-card"><div class="eyebrow">Allenamento consigliato</div><h2>${first.name}</h2><p>${first.focus} · ${first.duration} min</p><button data-routine="0">Visualizza routine ↗</button></div><div class="section-heading"><h2>La tua settimana</h2><button class="text-action" data-tab="stats">Vedi statistiche →</button></div><div class="grid-2"><div class="stat-card"><span class="stat-icon">▥</span><strong>3 / 3</strong><small>Allenamenti</small></div><div class="stat-card"><span class="stat-icon">◷</span><strong>165</strong><small>Minuti attivi</small></div></div><div class="section-heading"><h2>Livello ${state.level}</h2><span class="mini-label">${state.xp} / 900 XP</span></div><div class="card"><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,state.xp/9)}%"></div></div><p class="sub" style="margin-top:12px">${Math.max(0,900-state.xp)} XP al prossimo livello. Hai già fatto tanta strada!</p></div><div class="section-heading"><h2>Le tue routine</h2><button class="text-action" data-tab="routines">Vedi tutte →</button></div>${routineCard(state.routines[1],1)}`)}
function routineCard(r,i){return `<button class="card routine-card" data-routine="${i}"><div class="row"><span class="routine-icon">${r.color}</span><div><h3>${r.name}</h3><p>${r.focus}</p></div><span class="chevron">›</span></div><div class="meta"><span>◷ ${r.duration} min</span><span>▤ ${r.exercises.length} esercizi</span></div></button>`}
function routines(){return shell(`${top(`<button class="icon-btn" data-action="new-routine" aria-label="Aggiungi routine">＋</button>`)}<div class="eyebrow">Allenati con un piano</div><h1 class="title">Le tue routine</h1><p class="sub">Scegli il tuo prossimo allenamento.</p><div class="section-heading"><h2>Pronte per te</h2><span class="pill">${state.routines.length} routine</span></div>${state.routines.map(routineCard).join('')}<div class="card" style="border-style:dashed;text-align:center;margin-top:17px"><div style="font-size:28px;color:#c9fa64">＋</div><strong>Crea la tua routine</strong><p class="sub" style="margin:7px 0 13px">Personalizzazione disponibile nella prossima fase.</p><button class="small-btn" data-action="new-routine">Scopri di più →</button></div>`)}
function detail(){const r=state.routines[state.selectedRoutine];return shell(`${top(`<button class="icon-btn" data-action="back-routines" aria-label="Torna alle routine">×</button>`)}<div class="eyebrow">La tua routine</div><h1 class="title">${r.name}</h1><p class="sub">${r.focus}</p><div class="grid-2" style="margin-top:22px"><div class="stat-card"><span class="stat-icon">◷</span><strong>${r.duration}</strong><small>Minuti previsti</small></div><div class="stat-card"><span class="stat-icon">▤</span><strong>${r.exercises.length}</strong><small>Esercizi</small></div></div><div class="section-heading"><h2>Esercizi</h2><span class="mini-label">${r.exercises.length} totali</span></div><div class="card">${r.exercises.map((x,i)=>`<div class="exercise row"><span class="routine-icon" style="width:34px;height:34px;font-size:13px">${String(i+1).padStart(2,'0')}</span><div><h3>${x.name}</h3><p>${x.detail}</p></div></div>`).join('')}</div><div class="sticky-action"><button class="primary" data-action="start-workout">Inizia allenamento →</button></div>`,false)}
function workout(){const r=state.routines[state.activeRoutine ?? 0],total=r.exercises.reduce((n,x)=>n+x.sets,0),done=Object.values(state.completed).filter(Boolean).length;return shell(`${top(`<button class="icon-btn" data-action="exit-workout" aria-label="Esci dall'allenamento">×</button>`)}<div class="eyebrow">Allenamento in corso</div><h1 class="title">${r.name}</h1><div class="workout-header"><div class="row space"><div><strong>${done} / ${total}</strong><p>Serie completate</p></div><span class="pill">${Math.round(done/total*100)}%</span></div><div class="progress-track" style="margin-top:14px"><div class="progress-fill" style="width:${done/total*100}%"></div></div></div><p class="sub">Segna le serie completate. Puoi modificare peso e ripetizioni durante la sessione.</p>${r.exercises.map((x,i)=>`<div class="card" style="margin-top:12px"><div class="row space"><div><h2 style="font:700 16px Outfit;margin:0">${x.name}</h2><span class="mini-label">${x.sets} serie previste</span></div><span style="color:#c9fa64;font-size:19px">${i===0?'◆':'◇'}</span></div><div class="workout-set"><span></span><span style="text-align:center">kg</span><span style="text-align:center">rip.</span><span></span></div>${Array.from({length:x.sets},(_,j)=>`<div class="workout-set"><span>${j+1}</span><input type="number" min="0" value="${x.weight}" aria-label="Peso serie ${j+1} ${x.name}"><input type="number" min="0" value="${x.reps}" aria-label="Ripetizioni serie ${j+1} ${x.name}"><button data-set="${i}-${j}" class="${state.completed[`${i}-${j}`]?'done':''}" aria-label="${state.completed[`${i}-${j}`]?'Annulla':'Completa'} serie ${j+1} ${x.name}">✓</button></div>`).join('')}</div>`).join('')}<button class="primary" data-action="finish-workout" style="margin-top:23px">Termina allenamento</button><button class="small-btn" data-action="exit-workout" style="display:block;margin:10px auto">Torna alle routine</button>`,false)}
function stats(){const weekly=state.period==='week';const values=weekly?[35,65,20,82,54,100,12]:[40,60,52,84,67,100,73];return shell(`${top()}<div class="eyebrow">I numeri raccontano</div><h1 class="title">I tuoi progressi</h1><p class="sub">La costanza diventa visibile.</p><div class="segmented" style="margin:23px 0 17px"><button data-period="week" class="${weekly?'active':''}">Settimana</button><button data-period="month" class="${!weekly?'active':''}">Mese</button></div><div class="grid-2"><div class="stat-card"><span class="stat-icon">▥</span><strong>${weekly?'3':'12'}</strong><small>Allenamenti</small></div><div class="stat-card"><span class="stat-icon">◷</span><strong>${weekly?'165':'680'}</strong><small>Minuti attivi</small></div></div><div class="section-heading"><h2>Attività</h2><span class="mini-label">${weekly?'Questa settimana':'Questo mese'}</span></div><div class="card"><div class="chart">${values.map((v,i)=>`<div class="chart-col"><div class="chart-bar ${i===5?'current':''}" style="height:${v}%"></div><small>${weekly?['L','M','M','G','V','S','D'][i]:['1','5','10','15','20','25','30'][i]}</small></div>`).join('')}</div><p class="sub" style="margin-top:16px">${weekly?'Hai raggiunto il tuo obiettivo settimanale.':'Stai costruendo un ottimo ritmo.'}</p></div><div class="section-heading"><h2>Traguardi</h2></div><div class="card"><div class="list-row"><span class="circle-icon">★</span><div><strong>Prima settimana completa</strong><small>3 allenamenti in 7 giorni</small></div><span class="pill" style="margin-left:auto">+50 XP</span></div><div class="list-row"><span class="circle-icon">↗</span><div><strong>Record personale</strong><small>Panca piana · 65 kg</small></div><span class="pill" style="margin-left:auto">+30 XP</span></div></div><div class="section-heading"><h2>In totale</h2></div><div class="grid-2"><div class="stat-card"><strong>${state.workouts}</strong><small>Sessioni</small></div><div class="stat-card"><strong>${state.minutes}</strong><small>Minuti attivi</small></div></div>`)}
function profile(){return shell(`${top(`<span class="pill">Livello ${state.level}</span>`)}<div class="eyebrow">Il tuo spazio</div><h1 class="title">Profilo</h1><div class="profile-head"><div class="avatar">${e(state.name[0]||'A')}</div><div><h2>${e(state.name)}</h2><p>In cammino verso la tua forma migliore</p></div></div><div class="card"><div class="row space"><strong>Livello ${state.level}</strong><span class="pill">✦ ${state.xp} XP</span></div><div class="progress-track" style="margin-top:16px"><div class="progress-fill" style="width:${Math.min(100,state.xp/9)}%"></div></div><p class="sub" style="margin-top:10px">${Math.max(0,900-state.xp)} XP al livello successivo</p></div><div class="section-heading"><h2>Il mio obiettivo</h2></div><div class="card"><div class="row"><span class="circle-icon">◎</span><div><strong>${e(state.goal)}</strong><small>Obiettivo personale</small></div></div></div><div class="section-heading"><h2>Impostazioni demo</h2></div><div class="card"><button class="list-row" data-action="edit-profile" style="width:100%;background:none;border-left:0;border-right:0;border-top:0;color:#fff;text-align:left"><span class="circle-icon">✎</span><div><strong>Modifica profilo</strong><small>Nome e obiettivo</small></div><span class="chevron">›</span></button><div class="list-row"><span class="circle-icon">♧</span><div><strong>CoreFit Premium</strong><small>Funzionalità prevista</small></div></div></div><button class="logout" data-action="logout">Esci dalla demo →</button>`)}
function editProfile(){return shell(`${top(`<button class="icon-btn" data-action="profile" aria-label="Torna al profilo">×</button>`)}<div class="eyebrow">Personalizza</div><h1 class="title">Modifica profilo</h1><p class="sub">Queste modifiche restano nel browser.</p><form id="profile-form" style="margin-top:25px"><label class="field"><span>Nome</span><input name="name" value="${e(state.name)}" maxlength="30" required></label><label class="field"><span>Obiettivo</span><input name="goal" value="${e(state.goal)}" maxlength="70" required></label><button class="primary" type="submit">Salva modifiche</button></form>`,false)}
function finished(){return shell(`${top()}<div class="onboard-art art-2" style="min-height:230px;margin:20px 0" aria-hidden="true"></div><div class="eyebrow">Sessione completata</div><h1 class="title" style="font-size:36px">Ottimo lavoro, ${e(state.name)}!</h1><p class="sub">Un altro passo verso il tuo obiettivo.</p><div class="grid-2" style="margin:25px 0"><div class="stat-card"><span class="stat-icon">✦</span><strong>+100</strong><small>XP guadagnati</small></div><div class="stat-card"><span class="stat-icon">✓</span><strong>${Object.values(state.completed).filter(Boolean).length}</strong><small>Serie completate</small></div></div><button class="primary" data-action="finish-home">Torna alla home</button>`,false)}
function render(){const screens={onboarding,login,home,routines,detail,workout,stats,profile,editProfile,finished};app.innerHTML=(screens[state.screen]||home)();app.querySelector('.screen')?.scrollTo(0,0)}
app.addEventListener('click',event=>{const el=event.target.closest('[data-action],[data-tab],[data-routine],[data-set],[data-period]');if(!el)return;if(el.dataset.tab){state.tab=el.dataset.tab;go(el.dataset.tab);return}if(el.dataset.routine!==undefined){state.selectedRoutine=Number(el.dataset.routine);go('detail');return}if(el.dataset.set){state.completed[el.dataset.set]=!state.completed[el.dataset.set];save();render();return}if(el.dataset.period){state.period=el.dataset.period;save();render();return}switch(el.dataset.action){case 'next-onboard':if(state.onboard<2){state.onboard++;save();render()}else go('login');break;case 'skip-onboard':go('login');break;case 'demo-login':state.tab='home';go('home');break;case 'profile':state.tab='profile';go('profile');break;case 'back-routines':state.tab='routines';go('routines');break;case 'start-workout':state.activeRoutine=state.selectedRoutine;state.startedAt=Date.now();state.completed={};go('workout');break;case 'exit-workout':state.tab='routines';go('routines');break;case 'finish-workout':state.workouts++;state.xp+=100;state.minutes+=state.routines[state.activeRoutine].duration;go('finished');break;case 'finish-home':state.tab='home';go('home');break;case 'edit-profile':go('editProfile');break;case 'logout':go('login');break;case 'new-routine':alert('La creazione di routine arriverà nella prossima fase. In questa demo puoi esplorare le routine già presenti.');break}});
app.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='login-form'){state.tab='home';go('home')}if(form.id==='profile-form'){const data=new FormData(form);state.name=String(data.get('name')).trim()||'Alex';state.goal=String(data.get('goal')).trim()||defaultData.goal;state.tab='profile';go('profile')}});
render();
